insert into public.learning_tracks
  (slug, title, description, category, difficulty, lesson_count,
   est_minutes, icon_name, accent_color, is_featured, featured_rank)
values
  ('investing-basics', 'Investing Basics',
   'Start here: the first principles of investing — compounding, the major asset classes, risk, diversification, low-cost portfolios, and what fees actually cost you.',
   'Investing Basics', 'Beginner', 6, 155, 'TrendingUp', 'var(--color-accent)', true, 1),
  ('reading-financial-statements', 'Reading Financial Statements',
   'Decode the three statements every public company files, the ratios analysts use, how to navigate a 10-K on EDGAR, and the red flags that warn of low-quality earnings.',
   'Reading Financials', 'Intermediate', 7, 205, 'BarChart2', 'var(--color-success)', true, 2),
  ('macro-and-the-fed', 'Macro & The Fed',
   'How the Federal Reserve shapes the economy: dual mandate, the federal funds rate, inflation and CPI, business cycles, and why monetary policy moves markets.',
   'Macro & Economy', 'Intermediate', 6, 165, 'Landmark', '#a78bfa', false, null),
  ('options-and-derivatives', 'Options & Derivatives',
   'A serious introduction to calls, puts, payoffs, the Greeks, the basic strategies, plus futures, forwards, and what implied volatility (and the VIX) actually mean.',
   'Options & Derivatives', 'Advanced', 7, 235, 'Layers', '#f97316', false, null),
  ('personal-finance-foundations', 'Personal Finance Foundations',
   'Build the financial base that makes investing possible: budgeting, emergency funds, debt, credit, insurance, and goal-setting that actually sticks.',
   'Personal Finance', 'Beginner', 6, 150, 'PiggyBank', '#fbbf24', true, 3),
  ('retirement-planning', 'Retirement Planning',
   'Why retirement accounts matter, Social Security basics, how 401(k)s and IRAs differ, contribution limits, and the tax mechanics that make compounding worth more.',
   'Retirement', 'Beginner', 6, 160, 'Wallet', '#10b981', false, null),
  ('crypto-and-digital-assets', 'Crypto & Digital Assets',
   'A skeptical, plain-English tour of blockchain, Bitcoin, Ethereum, stablecoins, custody, and the specific risks regulators keep flagging.',
   'Crypto', 'Intermediate', 5, 140, 'Bitcoin', '#22d3ee', false, null),
  ('taxes-for-investors', 'Taxes for Investors',
   'What the IRS actually does with your trades: short vs long-term capital gains, qualified dividends, wash sales, cost basis, and tax-loss harvesting.',
   'Taxes', 'Intermediate', 5, 140, 'Receipt', '#ef4444', false, null),
  ('markets-and-trading-mechanics', 'Markets & Trading Mechanics',
   'How orders actually get filled: exchanges, market vs limit vs stop orders, settlement, the bid-ask spread, and why microstructure matters.',
   'Markets & Trading', 'Beginner', 5, 130, 'LineChart', '#3b82f6', false, null),
  ('bonds-and-fixed-income', 'Bonds & Fixed Income',
   'Bonds from first principles: coupons and par, the inverse price-yield relationship, Treasuries vs corporates, credit risk, duration, and what the yield curve signals.',
   'Markets & Trading', 'Intermediate', 6, 170, 'ShieldCheck', '#84cc16', false, null),
  ('etfs-vs-mutual-funds', 'ETFs vs Mutual Funds',
   'Both pool capital — but they trade, cost, and tax differently. Learn the mechanics, fees, tax efficiency, and how to pick the right one.',
   'Investing Basics', 'Beginner', 5, 120, 'Briefcase', '#06b6d4', true, 4),
  ('behavioral-finance-and-risk', 'Behavioral Finance & Risk',
   'The biases your brain runs by default — loss aversion, recency, herding, overconfidence — and the habits that beat them.',
   'Behavioral Finance', 'Intermediate', 5, 130, 'Brain', '#ec4899', true, 5)
