-- Track 1: investing-basics --------------------------------------------------
insert into public.lesson_questions
  (lesson_id, position, prompt, choices, correct_index, explanation, source_key)
values
  ((select id from public.track_lessons where slug = 'why-invest' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   1, 'Why does saving alone usually fall short of a long-term goal?',
   jsonb_build_array('Banks pay 0% interest by law','Inflation erodes the real value of cash over time','Saving accounts cannot be opened by individuals','Tax rates on savings are higher than on stocks'),
   1, 'Over decades, inflation reduces the purchasing power of cash. Investing in productive assets aims to grow money faster than prices rise.',
   'lesson:investing-basics:why-invest:q1'),
  ((select id from public.track_lessons where slug = 'why-invest' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   2, 'What does compound interest mean?',
   jsonb_build_array('Interest computed only on the original deposit','Interest the bank pays once a year','Interest paid on principal and on accumulated interest','A government subsidy on savings'),
   2, 'Compound interest is interest earned on both the original principal and the interest that has already accrued — the SEC defines it as interest on interest.',
   'lesson:investing-basics:why-invest:q2'),
  ((select id from public.track_lessons where slug = 'asset-classes' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   1, 'Which of these best describes a stock?',
   jsonb_build_array('A loan you make to the government','A share of ownership in a company','A guarantee of a fixed annual payment','A type of insurance policy'),
   1, 'A stock represents partial ownership of a company—shareholders may receive dividends and a vote on certain decisions.',
   'lesson:investing-basics:asset-classes:q1'),
  ((select id from public.track_lessons where slug = 'asset-classes' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   2, 'A bond is best described as what?',
   jsonb_build_array('Equity ownership in a corporation','A debt security — essentially an IOU','A non-tradeable savings account','A type of derivative contract'),
   1, 'The SEC describes a bond as a debt security where the issuer promises to repay principal at maturity and to pay interest along the way.',
   'lesson:investing-basics:asset-classes:q2'),
  ((select id from public.track_lessons where slug = 'risk-and-return' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   1, 'In general, the relationship between expected return and risk is:',
   jsonb_build_array('Inverse — higher return implies lower risk','Unrelated','Positive — higher expected return demands accepting higher risk','Determined entirely by the investor''s broker'),
   2, 'Higher expected returns generally compensate investors for taking on more risk—there is no risk-free shortcut to high returns.',
   'lesson:investing-basics:risk-and-return:q1'),
  ((select id from public.track_lessons where slug = 'risk-and-return' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   2, 'A longer time horizon typically lets an investor:',
   jsonb_build_array('Avoid all market risk','Tolerate more short-term volatility in pursuit of higher expected returns','Skip diversification','Earn guaranteed returns'),
   1, 'A longer horizon gives more time to recover from drawdowns, which is why long-term investors can usually hold a higher share of equities.',
   'lesson:investing-basics:risk-and-return:q2'),
  ((select id from public.track_lessons where slug = 'diversification-and-allocation' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   1, 'Diversification primarily works by:',
   jsonb_build_array('Increasing the average return of a portfolio','Combining assets whose returns are not perfectly correlated','Eliminating all losses','Reducing taxes on capital gains'),
   1, 'Spreading capital across assets that do not move in lockstep lowers portfolio-level volatility without giving up most of the expected return.',
   'lesson:investing-basics:diversification-and-allocation:q1'),
  ((select id from public.track_lessons where slug = 'diversification-and-allocation' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   2, 'Asset allocation refers to:',
   jsonb_build_array('The brokerage you choose','The mix of asset categories like stocks, bonds, and cash in a portfolio','The timing of when to sell','The taxes owed on dividends'),
   1, 'Asset allocation is the split among broad asset classes — research suggests it drives most of the long-run variability of returns.',
   'lesson:investing-basics:diversification-and-allocation:q2'),
  ((select id from public.track_lessons where slug = 'first-portfolio' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   1, 'An index fund aims to do what?',
   jsonb_build_array('Beat the market by selecting top stocks','Track the performance of a specified market index','Hedge against currency risk','Provide guaranteed income'),
   1, 'An index fund is built to match — not beat — a benchmark, typically at very low cost.',
   'lesson:investing-basics:first-portfolio:q1'),
  ((select id from public.track_lessons where slug = 'first-portfolio' and track_id = (select id from public.learning_tracks where slug = 'investing-basics')),
   2, 'Dollar-cost averaging means:',
