   'lesson:reading-financial-statements:income-statement:q2'),
  ((select id from public.track_lessons where slug = 'balance-sheet' and track_id = (select id from public.learning_tracks where slug = 'reading-financial-statements')),
   1, 'The accounting identity says assets equal:',
   jsonb_build_array('Revenue plus expenses','Liabilities plus shareholders'' equity','Cash plus inventory','Dividends paid'),
   1, 'The fundamental identity: Assets = Liabilities + Equity. Every transaction must keep this balance.',
