  ((select id from public.track_lessons where slug = 'balance-sheet' and track_id = (select id from public.learning_tracks where slug = 'reading-financial-statements')),
   2, 'Working capital is most commonly defined as:',
   jsonb_build_array('Total assets minus total liabilities','Current assets minus current liabilities','Cash on hand only','Equity divided by debt'),
   1, 'Working capital is current assets minus current liabilities — a basic measure of short-term liquidity.',
