-- Track 12: behavioral-finance-and-risk --------------------------------------
insert into public.lesson_questions
  (lesson_id, position, prompt, choices, correct_index, explanation, source_key)
values
  ((select id from public.track_lessons where slug = 'loss-aversion' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   1, 'Loss aversion describes the tendency to:',
   jsonb_build_array('Avoid all risky investments','Feel losses more strongly than equivalent gains','Always sell winners early','Take more risk after a loss'),
   1, 'Kahneman and Tversky showed that losses hurt roughly twice as much psychologically as equivalent gains feel good.',
   'lesson:behavioral-finance-and-risk:loss-aversion:q1'),
  ((select id from public.track_lessons where slug = 'loss-aversion' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   2, 'A common consequence of loss aversion for investors is:',
   jsonb_build_array('Better long-term returns','Refusing to sell losing positions, hoping to "get back to even"','Eagerly buying more stocks during downturns','Eliminating taxes'),
   1, 'Loss-averse investors often hold losers too long and sell winners too early — the "disposition effect".',
   'lesson:behavioral-finance-and-risk:loss-aversion:q2'),
  ((select id from public.track_lessons where slug = 'anchoring-and-recency' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   1, 'Anchoring bias is:',
   jsonb_build_array('Relying too heavily on the first piece of information encountered','A type of currency trade','Tracking only S&P 500 stocks','Refusing to use leverage'),
   0, 'People anchor on an initial number (e.g. a stock''s purchase price) even when it''s no longer relevant.',
   'lesson:behavioral-finance-and-risk:anchoring-and-recency:q1'),
  ((select id from public.track_lessons where slug = 'anchoring-and-recency' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   2, 'Recency bias is the tendency to:',
   jsonb_build_array('Overweight recent events when forecasting','Underweight recent events','Buy older companies','Sell only on Fridays'),
   0, 'Recency causes investors to extrapolate the recent past into the future, often at exactly the wrong moments.',
   'lesson:behavioral-finance-and-risk:anchoring-and-recency:q2'),
  ((select id from public.track_lessons where slug = 'herding-and-fomo' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   1, 'Herding in financial markets refers to:',
   jsonb_build_array('Investors following the crowd, often ignoring their own analysis','A specific options strategy','A type of FINRA rule','A type of ETF'),
   0, 'Herding describes investors copying the crowd — even when independent analysis suggests caution.',
   'lesson:behavioral-finance-and-risk:herding-and-fomo:q1'),
  ((select id from public.track_lessons where slug = 'herding-and-fomo' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   2, 'FOMO often peaks when:',
   jsonb_build_array('Markets are bottoming','Prices have already risen sharply','The Fed cuts rates','A new earnings season starts'),
   1, 'Fear of missing out tends to peak after large rallies — when expected forward returns are typically lowest.',
   'lesson:behavioral-finance-and-risk:herding-and-fomo:q2'),
  ((select id from public.track_lessons where slug = 'overconfidence' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   1, 'Overconfidence in investing usually leads to:',
   jsonb_build_array('Holding fewer concentrated bets','More frequent trading and weaker net returns','Better outcomes','Higher dividend yields'),
   1, 'The Barber-Odean research showed individual investors who trade more frequently earn lower net returns.',
   'lesson:behavioral-finance-and-risk:overconfidence:q1'),
  ((select id from public.track_lessons where slug = 'overconfidence' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   2, 'Why is "I just got lucky" a useful internal phrase for investors?',
   jsonb_build_array('It improves compounding','It guards against confusing a good outcome with a good process','It signals to brokers','It''s required by FINRA'),
   1, 'Distinguishing luck from skill is what keeps a temporary win from inflating into systematic overconfidence.',
   'lesson:behavioral-finance-and-risk:overconfidence:q2'),
  ((select id from public.track_lessons where slug = 'building-better-habits' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   1, 'Pre-commitment devices in investing include:',
   jsonb_build_array('Automated contributions and rules-based rebalancing','Day-trading','Borrowing on margin','Buying lottery tickets'),
   0, 'Setting up automatic transfers and rebalance triggers takes future emotional decisions off the table.',
   'lesson:behavioral-finance-and-risk:building-better-habits:q1'),
  ((select id from public.track_lessons where slug = 'building-better-habits' and track_id = (select id from public.learning_tracks where slug = 'behavioral-finance-and-risk')),
   2, 'Rebalancing on a fixed schedule helps because it:',
