-- Track 12: behavioral-finance-and-risk (Intermediate) — 12 questions
insert into public.track_quiz_questions
  (track_id, position, prompt, choices, correct_index, explanation, difficulty, source_key)
values
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   1, 'Loss aversion describes:',
   jsonb_build_array('Refusal to take any risk','Stronger emotional response to losses than to equivalent gains','Avoidance of bonds','Risk-seeking after gains'),
   1, 'Kahneman & Tversky showed losses hurt roughly twice as much as equivalent gains feel good.',
   'Beginner', 'track:behavioral-finance-and-risk:q1'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   2, 'The disposition effect refers to:',
   jsonb_build_array('Selling winners early and holding losers too long','Frequent rebalancing','A type of tax','A specific options strategy'),
   0, 'The disposition effect is the loss-aversion-driven tendency to lock in gains too quickly and hold losers in hope.',
   'Intermediate', 'track:behavioral-finance-and-risk:q2'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   3, 'Anchoring bias is:',
   jsonb_build_array('Relying too heavily on the first piece of information you encounter','A boating term','A type of currency trade','Trading only large caps'),
   0, 'Anchoring causes investors to fix on a number — like a purchase price — even when it''s no longer relevant.',
   'Intermediate', 'track:behavioral-finance-and-risk:q3'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   4, 'Recency bias is the tendency to:',
   jsonb_build_array('Underweight recent events','Overweight recent events when forecasting','Ignore data','Trust old data only'),
   1, 'Recency causes extrapolation of the recent past, leading to chasing winners and abandoning losers.',
   'Intermediate', 'track:behavioral-finance-and-risk:q4'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   5, 'Confirmation bias is:',
   jsonb_build_array('Looking for evidence that confirms your existing view','Ignoring all evidence','Reading only contrary opinions','Refusing to invest'),
   0, 'Confirmation bias filters new information through our existing beliefs, often blinding us to disconfirming evidence.',
   'Intermediate', 'track:behavioral-finance-and-risk:q5'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   6, 'Herding in markets describes:',
   jsonb_build_array('Investors following the crowd','A type of ETF','A bond strategy','A regulator-imposed rule'),
   0, 'Herding behavior contributes to bubbles and crashes — flows compound on themselves.',
   'Beginner', 'track:behavioral-finance-and-risk:q6'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   7, 'Overconfidence is correlated with:',
   jsonb_build_array('Better investment returns','Higher trading frequency and lower net returns','Lower trading costs','Greater diversification'),
   1, 'Barber-Odean research showed individual investors who trade most underperform — overconfidence is a key driver.',
   'Intermediate', 'track:behavioral-finance-and-risk:q7'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   8, 'Mental accounting refers to:',
   jsonb_build_array('Treating money differently depending on source or label','A type of bookkeeping software','A tax-preparation method','A regulatory framework'),
   0, 'Mental accounting causes people to treat "found money" or "tax refund" dollars differently from earned dollars — even though they''re fungible.',
   'Advanced', 'track:behavioral-finance-and-risk:q8'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   9, 'A pre-commitment device is:',
   jsonb_build_array('A way to lock in future behavior to counter present-bias','A type of options contract','A federal tax form','A trading algorithm'),
   0, 'Pre-commitment devices (e.g., automatic contributions, rebalancing rules) protect against future emotional decisions.',
   'Intermediate', 'track:behavioral-finance-and-risk:q9'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   10, 'Sequence of returns risk refers to:',
   jsonb_build_array('Risk that prices change in random order','The risk that the order of returns near retirement materially affects outcomes','Risk-free returns','A specific bond ladder'),
   1, 'Early-retirement losses can permanently damage a portfolio''s ability to support withdrawals, even if average returns are identical.',
   'Advanced', 'track:behavioral-finance-and-risk:q10'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   11, 'Why do rules-based rebalancing schedules help most investors?',
   jsonb_build_array('They increase trading costs','They force selling what has risen and buying what has fallen, counter to emotion','They eliminate taxes','They predict the market'),
   1, 'Periodic rebalancing acts as a contrarian force against natural emotional patterns.',
   'Intermediate', 'track:behavioral-finance-and-risk:q11'),
  ((select id from public.learning_tracks where slug = 'behavioral-finance-and-risk'),
   12, 'Prospect theory is most associated with:',
   jsonb_build_array('Markowitz and Sharpe','Kahneman and Tversky','Black and Scholes','Modigliani and Miller'),
   1, 'Kahneman and Tversky''s prospect theory describes how people actually make decisions under risk — including loss aversion.',
   'Advanced', 'track:behavioral-finance-and-risk:q12')
on conflict (source_key) do nothing;

